    fortiapi::Field<std::vector<VlanEntry>> vlan;  // Configure VLAN assignment priority.
    fortiapi::Field<std::string> type;  // Indication of switch type, physical or virtual.
    fortiapi::Field<std::string> owner_vdom;  // VDOM which owner of port belongs to.
    fortiapi::Field<std::string> flow_identity;  // Flow-tracking netflow ipfix switch identity in hex format(00000000-FFFFFFFF default=0).
    fortiapi::Field<std::string> staged_image_version;  // Staged image version for FortiSwitch.
    fortiapi::Field<std::uint32_t> delayed_restart_trigger;  // Delayed restart triggered for this FortiSwitch.
    fortiapi::Field<std::string> firmware_provision;  // Enable/disable provisioning of firmware to FortiSwitches on join connection.
    fortiapi::Field<std::string> firmware_provision_version;  // Firmware version to provision to this FortiSwitch on bootup (major.minor.build, i.e. 6.2.1234).
    fortiapi::Field<std::string> firmware_provision_latest;  // Enable/disable one-time automatic provisioning of the latest firmware version.
    fortiapi::Field<std::vector<PortsEntry>> ports;  // Managed-switch port list.
