    fortiapi::Field<StormControl> storm_control;  // Configuration method to edit FortiSwitch storm control for measuring traffic activity using data rates to prevent traffic disruption.
    fortiapi::Field<std::vector<MirrorEntry>> mirror;  // Configuration method to edit FortiSwitch packet mirror.
    fortiapi::Field<std::vector<StaticMacEntry>> static_mac;  // Configuration method to edit FortiSwitch Static and Sticky MAC.
    fortiapi::Field<std::vector<CustomCommandEntry>> custom_command;  // Configuration method to edit FortiSwitch commands to be pushed to this FortiSwitch device upon rebooting the FortiGate switch controller or the FortiSwitch.
    fortiapi::Field<std::vector<DhcpSnoopingStaticClientEntry>> dhcp_snooping_static_client;  // Configure FortiSwitch DHCP snooping static clients.
    fortiapi::Field<IgmpSnooping> igmp_snooping;  // Configure FortiSwitch IGMP snooping global settings.
    fortiapi::Field<_8021XSettings> _802_1X_settings;  // Configuration method to edit FortiSwitch 802.1X global settings.

